Como o resultado final desejado é uma **máscara única** onde cada banda $i$ atende à condição de sua lista de valores, e precisamos que isso ocorra para *todas* as bandas simultaneamente, podemos usar `ee.Image.reduce(ee.Reducer.any())` ou `ee.Image.and()` em vez do empilhamento complexo.

### Código Refatorado (Sugestão de Otimização/Clareza)

Vou refatorar `selectPixels` para ser mais explícito sobre a interseção, mantendo a funcionalidade desejada (selecionar pixels que satisfazem a condição de **cada uma** das 6 bandas ao mesmo tempo).

```javascript
// Define uma função para selecionar os pixels cujos valores estão na lista para cada banda
function selectPixelsOptimized(image, valuesDict, bandsList) {

  var allBandMasks = bandsList.map(function(band) {
    var bandName = ee.String(band);
    var valuesList = ee.List(valuesDict.get(bandName));

    // 1. Criar uma imagem binária para cada valor permitido nesta banda
    var individualMasks = valuesList.map(function(val) {
      // Cria uma máscara onde o pixel é exatamente igual ao valor 'val' para esta banda
      return image.select(bandName).eq(ee.Number(val)).rename(bandName + '_mask');
    });

    // 2. Combinar as máscaras individuais para esta banda (União/OR lógico)
    // Se o pixel for um de qualquer um dos valores permitidos, ele é marcado como 1 nesta banda.
    // Usa reduce(ee.Reducer.any()) que funciona como um OR lógico em imagens.
    var combinedMaskForBand = ee.ImageCollection(individualMasks).reduce(ee.Reducer.any());

    return combinedMaskForBand;
  });

  // 3. Combinar as máscaras de todas as bandas (Interseção/AND lógico)
  // Aqui, precisamos que o pixel seja marcado como 1 em TODAS as máscaras de banda (B, G, R, N, NDVI, NDWI).
  // Usamos reduce(ee.Reducer.min()) sobre máscaras binárias (onde 1=presente, 0=ausente)
  // Isso garante que apenas onde TODOS os valores são 1, o resultado será 1.
  var finalCombinedMask = ee.ImageCollection(allBandMasks).reduce(ee.Reducer.min());

  // Aplica a máscara final na imagem original (x3)
  return image.updateMask(finalCombinedMask.gte(1)); // Usar gte(1) para garantir que estamos mascarando por 1
}

