print(teste_count_optimized, 'teste_count_optimized');

Map.addLayer(x3, {bands: ['R_p30', 'G_p30', 'B_p30'], min: 0, max: 1500}, 'Original Image');

// Se você quiser visualizar a área selecionada (apenas pixels que sobreviveram)
Map.addLayer(teste_count_optimized, {
